import{_ as o,c as a,o as t,ah as c}from"./chunks/framework.oAolcYhj.js";const u=JSON.parse('{"title":"Test data for local manual screenshots","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/qonnectra-demo-data/README.md","filePath":"scripts/qonnectra-demo-data/README.md"}'),s={name:"scripts/qonnectra-demo-data/README.md"};function d(i,e,r,n,l,p){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="test-data-for-local-manual-screenshots" tabindex="-1">Test data for local manual screenshots <a class="header-anchor" href="#test-data-for-local-manual-screenshots" aria-label="Permalink to &quot;Test data for local manual screenshots&quot;">​</a></h1><p><code>testprojekt-export.json</code> is a 1:1 export of the real project <strong>&quot;Testprojekt&quot;</strong> from app.geodock.de (nodes, trenches, conduits, addresses, cables, fibers, microducts, areas including the associated reference data such as companies, conduit/cable types and flags). <code>scripts/setup-local-qonnectra.sh</code> imports this file into a fresh local instance automatically.</p><p>Deliberately <strong>not</strong> included: Container/ContainerType, FiberSplice, NodeStructure/slot configuration (patch panel modelling) and NetworkSchemaSettings (which node types are hidden in the network schema) - these are not (yet) part of the scope of the manual, or had no suitable API endpoint to export from.</p><h2 id="updating-the-data" tabindex="-1">Updating the data <a class="header-anchor" href="#updating-the-data" aria-label="Permalink to &quot;Updating the data&quot;">​</a></h2><p>The export was produced with a browser script (JavaScript, against the logged-in session on app.geodock.de), because the app has no ready-made &quot;export everything&quot; button. Short version, in case the data ever has to be pulled again:</p><ol><li>Log in to app.geodock.de (in the browser).</li><li>Through the browser console/DevTools, against <code>https://api.geodock.de/api/v1/</code>, fetch all pages for every required resource (<code>trench</code>, <code>conduit</code>, <code>trench_conduit_connection</code>, <code>microduct</code>, <code>microduct_connection</code>, <code>microduct_cable_connection</code>, <code>node</code>, <code>address</code>, <code>residential-unit</code>, <code>cable</code>, <code>cable_label</code>, <code>fiber</code>, <code>area</code>, each with <code>?project=&lt;id&gt;</code>, plus the global <code>attributes_*</code> and <code>flags</code> lists without a project filter) and merge them into a single JSON object. Careful: <code>trench</code>, <code>node</code>, <code>address</code> and <code>area</code> return a GeoJSON <code>FeatureCollection</code> per page (<code>results.features</code>), all other resources a plain <code>results</code> array - see <code>import_geodock_export.py</code> for the exact processing logic.</li><li>Save it as a JSON file and import it into the local instance with <code>import_geodock_export.py --file ... --force</code>.</li></ol><h2 id="import-command" tabindex="-1">Import command <a class="header-anchor" href="#import-command" aria-label="Permalink to &quot;Import command&quot;">​</a></h2><p><code>import_geodock_export.py</code> is copied by <code>setup-local-qonnectra.sh</code> into <code>local-app/backend/apps/api/management/commands/</code> (local-app/ is gitignored and is refilled from the checkout on every run). After that:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import_geodock_export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/file.json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--force]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Without <code>--force</code> an already existing local project &quot;Testprojekt&quot; is skipped (no re-import). With <code>--force</code> it is deleted completely first and imported again.</p>',10)])])}const m=o(s,[["render",d]]);export{u as __pageData,m as default};
